declare
 m jsonb := $manifest${"batch":"sail-result-2025-2026-10-28","event":{"id":"902a5f6d-c9fd-5f62-8dd7-aafbe28e045b","slug":"trat-regatta-2025","name":"Trat Regatta 2025","startDate":"2025-05-09","endDate":"2025-05-11","venue":"Laem Sok, Trat, Thailand","organizer":"Yacht Racing Association of Thailand","classes":["ILCA 4","ILCA 6","ILCA 7","Optimist"]},"sheet":{"id":"fa19c452-5c2b-513f-92dd-e3d98523e1e0","slug":"trat-regatta-2025-ilca4","name":"Trat Regatta 2025 — ILCA 4","boatClass":"ILCA 4","division":"Open","raceCount":3,"totalFleetSize":9,"entryType":"individual","minParticipants":1,"maxParticipants":1},"officialSource":{"url":"https://www.racingrulesofsailing.org/documents/141364","title":"Trat Regatta 2025 — ILCA 4 Open results","type":"pdf","provisional":false,"publicationStatus":"final","visuallyReviewed":true,"pdfSearch":null},"results":[{"eventKey":"trat-regatta-2025","sourceDocument":141364,"sourcePage":1,"sourceClass":"ILCA 4","boatClass":"ILCA 4","division":"Open","rank":1,"name":"CHANATIP TONGGLUM","sailOrBoardNumber":"217321","club":"YRAT","nationality":null,"gender":"M","officialBirthYear":2008,"sourceBirthYear":"2008","grossScore":4.0,"nettScore":4.0,"races":[{"raceNumber":1,"score":2.0,"code":null,"discarded":false,"raw":"2.0"},{"raceNumber":2,"score":1.0,"code":null,"discarded":false,"raw":"1.0"},{"raceNumber":3,"score":1.0,"code":null,"discarded":false,"raw":"1.0"}],"handicap":false,"sailorId":"d9337400-b506-5662-9c3c-9c657c5c947b","identityBasis":"Distinct full source name; no exact or close existing-name candidate. No DOB invented.","resultId":"94ee0d02-3e4a-5f92-9880-df746a518d7e","participants":[{"id":"1d5fec00-6d43-51cd-8259-f44ab17d99ec","sailorId":"d9337400-b506-5662-9c3c-9c657c5c947b","sourceName":"CHANATIP TONGGLUM","displayOrder":1,"role":"solo"}],"evidenceNotes":"Official source class: ILCA 4; page 1; source name: CHANATIP TONGGLUM; historic sail: 217321; club: YRAT; year field: 2008. Distinct full source name; no exact or close existing